import { test } from "node:test";
import assert from "node:assert/strict";
import { createEndpointRegistry } from "../src/webhooks/endpoints.js";
import { createDispatcher } from "../src/webhooks/dispatcher.js";
import { verify } from "../src/webhooks/signing.js";

// A subscriber that verifies every request exactly as documented, and answers with the next scripted status.
function setup(script = [200]) {
    let ms = Date.UTC(2026, 10, 20, 9, 0, 0);
    const clock = { now: () => ms };
    const sleep = async (d) => void (ms += d);
    const received = [];
    const transport = {
        async post(url, { headers, body }) {
            const check = verify({
                secret: "whsec_test",
                header: headers["webhook-signature"],
                body,
                nowSeconds: Math.floor(ms / 1000),
            });
            received.push({ url, headers, body, check });
            const status = script[Math.min(received.length - 1, script.length - 1)];
            if (status === "throw") throw new Error("ECONNRESET");
            return { status };
        },
    };
    const registry = createEndpointRegistry();
    registry.register({ id: "ep1", url: "https://shop.example/hooks", secret: "whsec_test", events: ["invoice.paid"] });
    registry.register({ id: "ep2", url: "https://other.example/hooks", secret: "whsec_other", events: ["customer.created"] });
    return { dispatcher: createDispatcher({ registry, transport, clock, sleep }), received };
}

const event = { id: "evt_1", type: "invoice.paid", data: { invoice: "in_77", amountCents: 4900 } };

test("only endpoints subscribed to the event type are called", async () => {
    const { dispatcher, received } = setup();
    const results = await dispatcher.publish(event);
    assert.equal(results.length, 1);
    assert.equal(received[0].url, "https://shop.example/hooks");
});

test("a first-attempt delivery carries a valid signature", async () => {
    const { dispatcher, received } = setup([200]);
    const [res] = await dispatcher.publish(event);
    assert.deepEqual(res, { delivered: true, attempts: 1 });
    assert.deepEqual(received[0].check, { ok: true });
});

test("retries after a 500 and succeeds", async () => {
    const { dispatcher } = setup([500, 200]);
    const [res] = await dispatcher.publish(event);
    assert.deepEqual(res, { delivered: true, attempts: 2 });
});

test("every retry is signed freshly enough for the subscriber to accept it", async () => {
    const { dispatcher, received } = setup([500, 503, 502, 200]);
    const [res] = await dispatcher.publish(event);
    console.log("verification per attempt:", received.map((r) => r.check.ok ? "ok" : r.check.reason).join(", "));
    assert.deepEqual(received.map((r) => r.check), [{ ok: true }, { ok: true }, { ok: true }, { ok: true }], "a retry 21 minutes in must still verify");
    assert.equal(res.delivered, true);
});

test("the signed timestamp moves forward with each attempt", async () => {
    const { dispatcher, received } = setup([500, 500, 200]);
    await dispatcher.publish(event);
    const stamps = received.map((r) => Number(/t=(\d+)/.exec(r.headers["webhook-signature"])[1]));
    assert.equal(stamps[1] - stamps[0], 60, "second attempt is sent after the 1 minute backoff");
    assert.equal(stamps[2] - stamps[1], 300, "third attempt is sent after the 5 minute backoff");
});

test("the webhook-id stays the same across retries so subscribers can dedupe", async () => {
    const { dispatcher, received } = setup([500, 200]);
    await dispatcher.publish(event);
    assert.equal(received[0].headers["webhook-id"], "evt_1");
    assert.equal(received[1].headers["webhook-id"], "evt_1");
    assert.equal(received[0].body, received[1].body);
});

test("a 400 is not retried", async () => {
    const { dispatcher, received } = setup([400]);
    const [res] = await dispatcher.publish(event);
    assert.deepEqual(res, { delivered: false, attempts: 1 });
    assert.equal(received.length, 1);
});

test("gives up after the last backoff and records every attempt", async () => {
    const { dispatcher } = setup(["throw"]);
    const [res] = await dispatcher.publish(event);
    assert.deepEqual(res, { delivered: false, attempts: 4 });
    assert.deepEqual(dispatcher.log().map((l) => l.status), [0, 0, 0, 0]);
});
